<?php require '../includes/functions.php';$u=require_role('department_admin');if(!$u['department_id']){http_response_code(403);exit('No department is assigned to this account.');}$pdo=db();$q=$pdo->prepare("SELECT COUNT(*) total,SUM(status='Submitted') new_count,SUM(status='Under Review') review_count,SUM(status='In Progress') progress_count,SUM(status IN ('Resolved','Closed')) resolved_count,SUM(expected_resolution_date<CURDATE() AND status NOT IN ('Resolved','Closed','Rejected')) overdue_count FROM grievances WHERE department_id=?");$q->execute([$u['department_id']]);$s=$q->fetch();$q=$pdo->prepare('SELECT g.id,g.tracking_number,g.title,g.status,g.created_at,g.expected_resolution_date,u.full_name citizen FROM grievances g JOIN users u ON u.id=g.citizen_id WHERE g.department_id=? ORDER BY g.created_at DESC');$q->execute([$u['department_id']]);$rows=$q->fetchAll();$pageTitle='Department dashboard';require '../includes/header.php';?><h1>Department dashboard</h1><div class="grid"><?php foreach(['Total'=>'total','New'=>'new_count','Under review'=>'review_count','In progress'=>'progress_count','Resolved'=>'resolved_count','Overdue'=>'overdue_count'] as $l=>$k):?><div class="card"><span><?=e($l)?></span><strong><?= (int)($s[$k]??0)?></strong></div><?php endforeach?></div><section class="panel"><h2>Department grievances</h2><form method="get" class="actions"><label>Status <select name="status"><option value="">All statuses</option><?php foreach(['Submitted','Under Review','Assigned','In Progress','Resolved','Closed','Rejected','Reopened'] as $st):?><option><?=e($st)?></option><?php endforeach?></select></label><label>Search <input name="q" placeholder="Tracking number or title"></label><button>Filter</button></form><table><tr><th>ID</th><th>Title</th><th>Citizen</th><th>Status</th><th>Due</th><th></th></tr><?php foreach($rows as $g):if(!empty($_GET['status'])&&$g['status']!==$_GET['status'])continue;if(!empty($_GET['q'])&&stripos($g['tracking_number'].' '.$g['title'],$_GET['q'])===false)continue;?><tr><td><?=e($g['tracking_number'])?></td><td><?=e($g['title'])?></td><td><?=e($g['citizen'])?></td><td><?=e($g['status'])?></td><td><?=e($g['expected_resolution_date']??'—')?></td><td><a href="<?=e(url('department/view.php?id='.$g['id']))?>">Process</a></td></tr><?php endforeach?></table></section><?php require '../includes/footer.php';?>
